package wang.robby.console.billinglab;
import org.junit.Test;
import static org.junit.Assert.*;
import wang.robby.console.billinglab.ScenarioEngine.*;
public class ScenarioSessionTest {
 @Test public void cancelOrGraceCannotUndoHold(){for(State s:new State[]{State.CANCELED,State.GRACE}){ScenarioSession x=new ScenarioSession();x.event("A",Product.PRO,State.ACTIVE);long until=x.records().get(0).validUntil;x.advanceDays(31);x.event("A",Product.PRO,State.HOLD);assertEquals(until,x.records().get(0).validUntil);assertEquals(ScenarioSession.Outcome.HOLD_REQUIRES_PAYMENT,x.event("A",Product.PRO,s));assertEquals(Tier.FREE,x.tier("A"));}}
 @Test public void graceCannotShortenPaidTimeOrExtendOnRepeat(){ScenarioSession x=new ScenarioSession();x.event("A",Product.PRO,State.ACTIVE);long paid=x.records().get(0).validUntil;x.event("A",Product.PRO,State.GRACE);long grace=x.records().get(0).validUntil;assertEquals(paid+3*ScenarioSession.DAY,grace);x.event("A",Product.PRO,State.GRACE);assertEquals(grace,x.records().get(0).validUntil);x.advanceDays(31);assertEquals(Tier.PRO,x.tier("A"));x.advanceDays(2);assertEquals(Tier.FREE,x.tier("A"));}
 @Test public void cancelGraceTogglingCannotExtendGrace(){ScenarioSession x=new ScenarioSession();x.event("A",Product.PRO,State.ACTIVE);long paid=x.records().get(0).validUntil;for(int i=0;i<3;i++){x.event("A",Product.PRO,State.GRACE);x.event("A",Product.PRO,State.CANCELED);}assertEquals(paid+3*ScenarioSession.DAY,x.records().get(0).validUntil);}
 @Test public void cacheLossThenEventStillRetainsOtherEntitlements(){ScenarioSession x=new ScenarioSession();x.event("A",Product.LIFETIME,State.ACTIVE);x.event("A",Product.PRO,State.ACTIVE);x.clearView();assertEquals(Tier.FREE,x.tier("A"));x.event("A",Product.PRO,State.REFUNDED);assertEquals(Tier.BASIC,x.tier("A"));}
 @Test public void cancellationPreservesOriginalBoundary(){ScenarioSession x=new ScenarioSession();x.event("A",Product.PLUS,State.ACTIVE);long until=x.records().get(0).validUntil;x.advanceDays(1);x.event("A",Product.PLUS,State.CANCELED);assertEquals(until,x.records().get(0).validUntil);assertEquals(Tier.PLUS,x.tier("A"));x.advanceDays(31);assertEquals(Tier.FREE,x.tier("A"));}
 @Test public void pendingCannotEraseExistingLifetime(){ScenarioSession x=new ScenarioSession();x.event("A",Product.LIFETIME,State.ACTIVE);assertEquals(ScenarioSession.Outcome.IGNORED,x.event("A",Product.LIFETIME,State.PENDING));assertEquals(Tier.BASIC,x.tier("A"));}
 @Test public void differentAccountsRetainDistinctTiersAfterRestore(){ScenarioSession x=new ScenarioSession();x.event("A",Product.LIFETIME,State.ACTIVE);x.event("B",Product.PRO,State.ACTIVE);x.clearView();x.restore();assertEquals(Tier.BASIC,x.tier("A"));assertEquals(Tier.PRO,x.tier("B"));}
 @Test public void revokedStaysOffUntilNewReceipt(){ScenarioSession x=new ScenarioSession();x.event("A",Product.LIFETIME,State.ACTIVE);x.event("A",Product.LIFETIME,State.REVOKED);assertEquals(ScenarioSession.Outcome.IGNORED,x.event("A",Product.LIFETIME,State.ACTIVE));assertEquals(Tier.FREE,x.tier("A"));}
 @Test public void expiredSnapshotDoesNotGrantBeforeOldDate(){ScenarioSession x=new ScenarioSession();x.event("A",Product.PRO,State.ACTIVE);x.event("A",Product.PRO,State.EXPIRED);assertEquals(Tier.FREE,x.tier("A"));}
}
